import json
from pathlib import Path
KEYS='about solutions journey monitor dashboard report discover hero1 hero2 tagline intro detect citizen municipal detectDesc citizenDesc municipalDesc closing language'.split()
FLOW='review respond verify demo privacy local pause resume running paused bin overflow litter scattered alerts approve added pending cases all id type location status follow received progress closed'.split()
FORM='start finish verified empty description photo save close selectType locationHint descHint required badPhoto saved updated temp filter preview demoPoint'.split()
ROLE='welcome chooseRole officer worker person enter changeRole tasks complete vehicles simulate violation plate evidence vehicleNote roleNote'.split()
D={}
def add(code,core,flow,form,role):
 d={}
 for keys,values in [(KEYS,core),(FLOW,flow),(FORM,form),(ROLE,role)]:
  parts=values.split('|')
  assert len(keys)==len(parts),(code,len(keys),len(parts),keys)
  d.update(zip(keys,parts))
 D[code]=d
